  "parameters": {
    "name": "portainer_docker_manager",
    "description": "Manage Docker containers through Portainer API.",
    "jsCode": "const PORTAINER_HOST = 'http://192.168.10.100:9000';
const ENDPOINT_ID = '2';
const API_KEY = 'ptr_FpajMpxwvz2Amp2PowM3pn1dxfAXUORx2u/qXjh81nc=';

const action = $input.item.json.action;
const container_id = $input.item.json.container_id;
const force = $input.item.json.force || 'false';

async function callPortainerAPI(method, path, params = {}) {
  const queryString = new URLSearchParams({ endpointId: ENDPOINT_ID, ...params }).toString();
  const url = `${PORTAINER_HOST}${path}?${queryString}`;

  const response = await fetch(url, {
    method: method,
    headers: {
      'X-API-Key': API_KEY,
      'Content-Type': 'application/json'
    }
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`Portainer API error (${response.status}): ${errorText}`);
  }

  const ct = response.headers.get('content-type');
  if (ct && ct.includes('application/json')) return await response.json();

  const text = await response.text();
  return text || { success: true };
}

let result;

try {
  switch (action) {

    case 'list_containers':
      result = await callPortainerAPI('GET', `/api/endpoints/${ENDPOINT_ID}/docker/containers/json`, { all: 'true' });
      result = result.map(c => ({
        id: c.Id.substring(0, 12),
        name: c.Names[0].replace('/', ''),
        image: c.Image,
        state: c.State,
        status: c.Status,
        ports: c.Ports.map(p => p.PublicPort ? `${p.PublicPort}:${p.PrivatePort}` : p.PrivatePort).join(', ')
      }));
      break;

    case 'start_container':
      if (!container_id) throw new Error('container_id is required');
      await callPortainerAPI('POST', `/api/endpoints/${ENDPOINT_ID}/docker/containers/${container_id}/start`);
      result = { message: `Container ${container_id} started` };
      break;

    case 'stop_container':
      if (!container_id) throw new Error('container_id is required');
      await callPortainerAPI('POST', `/api/endpoints/${ENDPOINT_ID}/docker/containers/${container_id}/stop`);
      result = { message: `Container ${container_id} stopped` };
      break;

    case 'restart_container':
      if (!container_id) throw new Error('container_id is required');
      await callPortainerAPI('POST', `/api/endpoints/${ENDPOINT_ID}/docker/containers/${container_id}/restart`);
      result = { message: `Container ${container_id} restarted` };
      break;

    case 'get_logs':
      if (!container_id) throw new Error('container_id is required');
      const logs = await callPortainerAPI('GET', `/api/endpoints/${ENDPOINT_ID}/docker/containers/${container_id}/logs`, {
        stdout: 'true',
        stderr: 'true',
        tail: '200'
      });
      result = { logs };
      break;

    case 'inspect_container':
      if (!container_id) throw new Error('container_id is required');
      const info = await callPortainerAPI('GET', `/api/endpoints/${ENDPOINT_ID}/docker/containers/${container_id}/json`);
      result = {
        id: info.Id,
        name: info.Name,
        state: info.State,
        config: info.Config,
        network: info.NetworkSettings,
        mounts: info.Mounts
      };
      break;

    case 'get_stats':
      if (!container_id) throw new Error('container_id is required');
      const stats = await callPortainerAPI('GET', `/api/endpoints/${ENDPOINT_ID}/docker/containers/${container_id}/stats`, { stream: 'false' });
      result = {
        cpu: stats.cpu_stats,
        mem: stats.memory_stats,
        net: stats.networks
      };
      break;

    case 'remove_container':
      if (!container_id) throw new Error('container_id is required');
      await callPortainerAPI('DELETE', `/api/endpoints/${ENDPOINT_ID}/docker/containers/${container_id}`, { force });
      result = { message: `Container ${container_id} removed` };
      break;

    case 'list_networks':
      result = await callPortainerAPI('GET', `/api/endpoints/${ENDPOINT_ID}/docker/networks`);
      result = result.map(n => ({
        id: n.Id.substring(0, 12),
        name: n.Name,
        driver: n.Driver
      }));
      break;

    case 'list_images':
      result = await callPortainerAPI('GET', `/api/endpoints/${ENDPOINT_ID}/docker/images/json`);
      result = result.map(i => ({
        id: i.Id.split(':')[1].substring(0, 12),
        tags: i.RepoTags,
        size: Math.round(i.Size / 1024 / 1024) + 'MB'
      }));
      break;

    default:
      throw new Error('Unknown action');
  }

  return { json: { success: true, action, data: result } };

} catch (e) {
  return { json: { success: false, action, error: e.message } };
}"
